import { useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, ArrowLeft, Bell, Bot, BriefcaseBusiness, Building2, Check, CheckCircle2, ChevronDown, ChevronRight, CircleDollarSign, Clock3, Download, FileCheck2, FileSearch, FileText, Gauge, HelpCircle, History, Inbox, LayoutDashboard, ListFilter, Loader2, LockKeyhole, Menu, MoreHorizontal, PanelLeftClose, Plus, Receipt, RefreshCw, Search, Settings, ShieldAlert, ShieldCheck, SlidersHorizontal, Sparkles, Upload, UserCheck, Users, WalletCards, X, XCircle } from 'lucide-react';
import { blacklist, budgets as seedBudgets, COMPANY_NAME, employees, initialAudits, initialReimbursements, initialRules, invoices, TENANT_ID } from './data';
import { AuthorizationService, AuthService, BudgetTransactionService, ConcurrencyError, createAuditEvaluation, decisionToWorkflow, DomainError, InvoiceVerificationService, OcrService, PaymentService, PersistenceService, TaskAssignmentService, workflowLabel, WorkflowStateMachine, CurrencyService } from './services';
import type { AuditRecord, Budget, BudgetReservation, CommandResult, Decision, ExpenseInvoiceDraft, Invoice, Reimbursement, RiskLevel, Rule, RuleField, RuleOperator, SessionUser } from './types';
import { EmployeePortal, type ClaimDraftInput } from './EmployeePortal';
import { LoginPage } from './LoginPage';

type Page = '工作台'|'报销审核'|'发票中心'|'风险中心'|'预算管理'|'规则引擎'|'员工管理'|'供应商管理'|'审核记录'|'系统设置';
const company = COMPANY_NAME;
const money = (n:number,currency='CNY') => CurrencyService.format(n,currency);
const emp = (id:string) => employees.find(e=>e.id===id)!;
const invoice = (id:string) => invoices.find(i=>i.id===id)!;
const claimDecision=(r:Reimbursement):Decision=>r.finalDecision||r.machineDecision||(r.workflowStatus==='WAITING_SUPPLEMENT'?'要求补充材料':r.workflowStatus==='SUSPENDED'?'挂起':'人工复核');
const seedReservations:BudgetReservation[]=initialReimbursements.filter(r=>r.reservationStatus==='RESERVED').map((r,i)=>({id:`RSV-SEED-${i+1}`,reimbursementId:r.id,budgetId:r.budgetId,amount:r.amount,status:'RESERVED',createdAt:'2026-09-07T01:00:00.000Z',updatedAt:'2026-09-07T01:00:00.000Z',idempotencyKey:`seed:${r.id}`}));
const downloadCsv=(name:string,headers:string[],rows:(string|number)[][])=>{const safe=(v:string|number)=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s=`'${s}`;return `"${s.replace(/"/g,'""')}"`};const csv='\ufeff'+[headers,...rows].map(row=>row.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)};
const pageHash:Record<Page,string>={'工作台':'dashboard','报销审核':'audit','发票中心':'invoices','风险中心':'risks','预算管理':'budgets','规则引擎':'rules','员工管理':'employees','供应商管理':'suppliers','审核记录':'logs','系统设置':'settings'};
const hashPage=()=>Object.entries(pageHash).find(([,hash])=>location.hash.slice(1).split('/')[0]===hash)?.[0] as Page||'工作台';

const nav: {name:Page; icon:any; group?:string}[] = [
  {name:'工作台',icon:LayoutDashboard},{name:'报销审核',icon:FileCheck2},
  {name:'发票中心',icon:Receipt,group:'业务管理'},{name:'风险中心',icon:ShieldAlert},{name:'预算管理',icon:WalletCards},{name:'规则引擎',icon:SlidersHorizontal},
  {name:'员工管理',icon:Users,group:'数据管理'},{name:'供应商管理',icon:Building2},{name:'审核记录',icon:History},
  {name:'系统设置',icon:Settings,group:'系统'}
];

function Status({value}:{value:string}) { const cls:Record<string,string>={'已通过':'自动通过','待支付':'挂起','支付失败':'驳回','待处理':'挂起','待补充材料':'挂起','已支付':'已报销','草稿':'未报销','识别中':'人工复核','验真中':'人工复核','审核中':'人工复核','已取消':'驳回'}; return <span className={`tag tag-${cls[value]||value}`}>{value}</span> }
function Risk({value}:{value:RiskLevel}) { return <span className={`risk risk-${value}`}><i/>{value}风险</span> }
function Empty({text='暂无数据'}:{text?:string}) { return <div className="empty"><Inbox/><p>{text}</p></div> }

export default function App(){
  const persisted=useMemo(()=>PersistenceService.load(),[]);
  const [sessionUser,setSessionUser]=useState<SessionUser|null>(()=>AuthService.current());
  const [page,setPage]=useState<Page>(hashPage);
  const [collapsed,setCollapsed]=useState(false);
  const [reimbursements,setReimbursements]=useState(persisted?.reimbursements||initialReimbursements);
  const [invoiceState,setInvoiceState]=useState<Invoice[]>(persisted?.invoices||invoices);
  const [budgetState,setBudgetState]=useState<Budget[]>(persisted?.budgets||seedBudgets);
  const [reservations,setReservations]=useState<BudgetReservation[]>(persisted?.reservations||seedReservations);
  const [commands,setCommands]=useState<CommandResult<unknown>[]>(persisted?.commands||[]);
  const [audits,setAudits]=useState(persisted?.audits||initialAudits);
  const [rules,setRules]=useState(persisted?.rules||initialRules);
  const [selectedId,setSelectedId]=useState('BX202609070005');
  const [toast,setToast]=useState('');
  const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),2600)};
  const navigate=(next:Page,replace=false)=>{setPage(next);const hash=`#${pageHash[next]}`;replace?history.replaceState(null,'',hash):history.pushState(null,'',hash)};
  useEffect(()=>{const sync=()=>setPage(hashPage());window.addEventListener('popstate',sync);window.addEventListener('hashchange',sync);if(!location.hash)navigate('工作台',true);return()=>{window.removeEventListener('popstate',sync);window.removeEventListener('hashchange',sync)}},[]);
  useEffect(()=>{PersistenceService.save({schemaVersion:4,tenantId:TENANT_ID,reimbursements,invoices:invoiceState,budgets:budgetState,rules,audits,reservations,commands})},[reimbursements,invoiceState,budgetState,rules,audits,reservations,commands]);
  const openAudit=(id:string)=>{setSelectedId(id);navigate('报销审核')};
  const updateDecision=(id:string,decision:Decision,note:string)=>{
    try{
      const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','报销单不存在');
      if(!sessionUser)throw new DomainError('UNAUTHENTICATED','登录已失效，请重新登录'); AuthorizationService.canApprove(sessionUser,r);
      const stored=PersistenceService.load()?.reimbursements.find(x=>x.id===id);if(stored&&stored.version!==r.version)throw new ConcurrencyError();
      const commandId=`${id}:${decision}:v${r.version}`;if(commands.some(c=>c.commandId===commandId)){notify('该操作已完成，无需重复提交');return}
      const target=decisionToWorkflow(decision);let updated=r;
      if(updated.workflowStatus==='SUSPENDED'||updated.workflowStatus==='WAITING_SUPPLEMENT')updated=WorkflowStateMachine.transition(updated,'AUDITING');
      updated=WorkflowStateMachine.transition(updated,target);
      updated={...updated,finalDecision:decision,route:decision==='自动通过'?'支付队列':decision==='升级审批'?'财务负责人 · 王敏':decision==='人工复核'?'普通财务 · 林琳':decision==='挂起'?'预算管理员':'系统自动决策'};
      if(decision==='要求补充材料')updated={...updated,supplementRequest:{reason:note||'请补充报销所需业务材料',items:['业务事由说明','与本次费用对应的业务凭证'],requestedAt:new Date().toISOString(),dueAt:new Date(Date.now()+3*24*3600_000).toISOString()}};
      const budget=budgetState.find(b=>b.id===r.budgetId);let reservation=reservations.find(x=>x.reimbursementId===id&&x.status==='RESERVED');
      if(decision==='自动通过'&&budget&&!reservation){const result=BudgetTransactionService.reserve(budget,updated,updated.amount,`${commandId}:reserve`,reservations);setBudgetState(v=>v.map(b=>b.id===budget.id?result.budget:b));reservation=result.reservation;setReservations(v=>[...v,result.reservation])}
      if(decision==='驳回'&&budget&&reservation){const result=BudgetTransactionService.release(budget,reservation);setBudgetState(v=>v.map(b=>b.id===budget.id?result.budget:b));setReservations(v=>v.map(x=>x.id===reservation!.id?result.reservation:x));updated={...updated,reservationStatus:'RELEASED'}}
      if(decision==='自动通过')updated=PaymentService.enqueue(updated);
      setReimbursements(v=>v.map(x=>x.id===id?updated:x));
      const audit:AuditRecord={id:`A${Date.now()}`,tenantId:TENANT_ID,reimbursementId:id,time:new Date().toLocaleString('zh-CN',{hour12:false}),aiResult:r.machineDecision||'人工复核',manualResult:decision,risk:r.risk,reviewer:sessionUser.name,reviewerId:sessionUser.id,note,action:'MANUAL_DECISION',beforeStatus:r.workflowStatus,afterStatus:updated.workflowStatus,ruleSetVersion:r.hits.map(h=>`${h.id}@${h.version}`).join(','),traceId:`TR-${Date.now().toString(36)}`};
      setAudits(v=>[audit,...v]);setCommands(v=>[...v,{commandId,result:{id,decision},completedAt:new Date().toISOString()}]);notify(`已完成处理：${decision}`);
    }catch(error){notify(error instanceof Error?error.message:'处理失败，请稍后重试')}
  };
  const reevaluate=(id:string)=>{
    const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','报销单不存在');
    const inv=invoiceState.find(i=>i.id===r.invoiceId),employee=emp(r.employeeId),budget=budgetState.find(b=>b.id===r.budgetId);if(!inv||!budget)throw new DomainError('BUDGET_NOT_FOUND','关联票据或预算不存在');
    const history=r.historyDuplicateId?[...invoiceState,{...inv,id:`HIST-${r.historyDuplicateId}`}]:invoiceState;
    const evaluation=createAuditEvaluation(r,inv,employee,budget,rules,history);
    const terminal=['REJECTED','PAID','CANCELLED'].includes(r.workflowStatus);
    const nextWorkflow=terminal?r.workflowStatus:decisionToWorkflow(evaluation.decision);
    setReimbursements(v=>v.map(x=>x.id===id?{...x,hits:evaluation.hits,priorityScore:evaluation.priorityScore,machineDecision:evaluation.decision,route:evaluation.route,workflowStatus:nextWorkflow,risk:evaluation.hits.some(h=>h.risk==='高')?'高':evaluation.hits.some(h=>h.risk==='中')?'中':'低',version:x.version+1}:x));
    setAudits(v=>[{id:`A${Date.now()}`,tenantId:TENANT_ID,reimbursementId:id,time:new Date().toLocaleString('zh-CN',{hour12:false}),aiResult:evaluation.decision,manualResult:'—',risk:r.risk,reviewer:'系统',note:`重新执行规则，命中 ${evaluation.hits.length} 条`,action:'RE_EVALUATE',beforeStatus:r.workflowStatus,afterStatus:nextWorkflow,ruleSetVersion:evaluation.ruleSetVersion,traceId:evaluation.traceId},...v]);
    return evaluation;
  };
  const claimTask=(id:string)=>{try{if(!sessionUser)throw new DomainError('UNAUTHENTICATED','登录已失效');const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','任务不存在');if(r.assignedTo===sessionUser.id){notify('该任务已由你认领');return}const updated=TaskAssignmentService.claim(r,sessionUser);setReimbursements(v=>v.map(x=>x.id===id?updated:x));notify('任务认领成功，处理时限为 2 小时')}catch(error){notify(error instanceof Error?error.message:'认领失败')}};
  const releaseTask=(id:string)=>{try{if(!sessionUser)throw new DomainError('UNAUTHENTICATED','登录已失效');const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','任务不存在');setReimbursements(v=>v.map(x=>x.id===id?TaskAssignmentService.release(r,sessionUser):x));notify('任务已释放，可重新认领')}catch(error){notify(error instanceof Error?error.message:'释放失败')}};
  const transferTask=(id:string,targetUserId:string)=>{try{if(!sessionUser)throw new DomainError('UNAUTHENTICATED','登录已失效');const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','任务不存在');setReimbursements(v=>v.map(x=>x.id===id?TaskAssignmentService.transfer(r,sessionUser,targetUserId):x));notify('任务已转派')}catch(error){notify(error instanceof Error?error.message:'转派失败')}};
  const settlePayment=(id:string,success:boolean)=>{try{const r=reimbursements.find(x=>x.id===id);if(!r)throw new DomainError('NOT_FOUND','报销单不存在');let updated=PaymentService.settle(r,success);const budget=budgetState.find(b=>b.id===r.budgetId),reservation=reservations.find(x=>x.reimbursementId===id&&x.status==='RESERVED');if(success&&budget&&reservation){const result=BudgetTransactionService.consume(budget,reservation);setBudgetState(v=>v.map(x=>x.id===budget.id?result.budget:x));setReservations(v=>v.map(x=>x.id===reservation.id?result.reservation:x));updated={...updated,reservationStatus:'CONSUMED'}}setReimbursements(v=>v.map(x=>x.id===id?updated:x));setAudits(v=>[{id:`A${Date.now()}`,tenantId:TENANT_ID,reimbursementId:id,time:new Date().toLocaleString('zh-CN',{hour12:false}),aiResult:r.machineDecision||'自动通过',manualResult:success?'支付成功':'支付失败',risk:r.risk,reviewer:'支付服务',note:success?'支付成功，冻结预算已转为实际支出':'支付失败，预算继续冻结，可安全重试',action:success?'PAYMENT_SETTLED':'PAYMENT_FAILED',beforeStatus:r.workflowStatus,afterStatus:updated.workflowStatus,traceId:`TR-PAY-${Date.now().toString(36)}`},...v]);notify(success?'支付成功，预算已正式扣减':'支付失败，预算仍保持冻结')}catch(error){notify(error instanceof Error?error.message:'支付处理失败')}};
  const retryPayment=(id:string)=>{try{setReimbursements(v=>v.map(x=>x.id===id?PaymentService.retry(x):x));notify('已重新加入支付队列')}catch(error){notify(error instanceof Error?error.message:'重试失败')}};
  const makeInvoices=(attachments:ExpenseInvoiceDraft[])=>attachments.map((attachment,index):Invoice=>({id:`INV-UP-${Date.now()}-${index}`,tenantId:TENANT_ID,number:attachment.invoiceNumber||`UP${Date.now().toString().slice(-8)}${index}`,code:attachment.invoiceCode||'',date:attachment.invoiceDate||new Date().toISOString().slice(0,10),seller:attachment.seller||'待确认商户',sellerTaxId:attachment.sellerTaxId||'',buyer:attachment.buyer||'待确认购买方',buyerTaxId:attachment.buyerTaxId||'',amount:Math.max(0,attachment.amount-(attachment.tax||0)),tax:attachment.tax||0,total:attachment.amount,currency:'CNY',item:attachment.item||attachment.purpose||attachment.category,verifyStatus:attachment.verifyStatus,source:attachment.fileName||'待上传票据',ocrConfidence:attachment.ocrConfidence||0}));
  const saveEmployeeClaim=(data:ClaimDraftInput)=>{if(!sessionUser||sessionUser.role!=='EMPLOYEE')return;const budget=budgetState.find(x=>x.id===data.budgetId);if(!budget){notify('请选择有效预算');return}const id=data.id||`BX-DRAFT-${Date.now()}`;const existing=reimbursements.find(x=>x.id===id);const total=data.attachments.reduce((sum,x)=>sum+x.amount,0);const draft:Reimbursement={id,tenantId:TENANT_ID,employeeId:sessionUser.employeeId,amount:total,currency:'CNY',category:data.category,submittedAt:existing?.submittedAt||'未提交',workflowStatus:'DRAFT',paymentStatus:'NOT_STARTED',risk:'低',priorityScore:0,invoiceId:existing?.invoiceId||'INV001',invoiceIds:existing?.invoiceIds||[],attachments:data.attachments,budgetId:budget.id,budgetName:budget.name,availableBudget:budget.total-budget.spent-budget.frozen,reservationStatus:'NONE',purpose:data.purpose,hits:[],route:'员工草稿',version:(existing?.version||0)+1};setReimbursements(v=>existing?v.map(x=>x.id===id?draft:x):[draft,...v]);notify('草稿已保存');};
  const submitEmployeeClaim=(data:ClaimDraftInput)=>{if(!sessionUser||sessionUser.role!=='EMPLOYEE')return;const budget=budgetState.find(x=>x.id===data.budgetId);if(!budget){notify('请选择有效预算');return}const total=data.attachments.reduce((sum,x)=>sum+x.amount,0);const existing=data.id?reimbursements.find(x=>x.id===data.id):undefined;const generated=makeInvoices(data.attachments);const id=existing?.workflowStatus==='REJECTED'?`BX-${Date.now()}`:(existing?.id||`BX-${Date.now()}`);const base:Reimbursement={id,tenantId:TENANT_ID,employeeId:sessionUser.employeeId,amount:total,currency:'CNY',category:data.category,submittedAt:new Date().toLocaleString('zh-CN',{hour12:false}),workflowStatus:'AUDITING',machineDecision:'人工复核',paymentStatus:'NOT_STARTED',risk:'低',priorityScore:75,invoiceId:generated[0].id,invoiceIds:generated.map(x=>x.id),attachments:data.attachments,budgetId:budget.id,budgetName:budget.name,availableBudget:budget.total-budget.spent-budget.frozen,reservationStatus:'NONE',purpose:data.purpose,hits:[],route:'财务审核队列',version:(existing?.version||0)+1,resubmissionOf:data.resubmissionOf};const evaluation=createAuditEvaluation(base,generated[0],emp(sessionUser.employeeId),budget,rules,[...invoiceState,...generated]);const computedRisk:RiskLevel=evaluation.hits.some(h=>h.risk==='高')?'高':evaluation.hits.some(h=>h.risk==='中')?'中':'低';const claim:Reimbursement={...base,machineDecision:evaluation.decision,workflowStatus:decisionToWorkflow(evaluation.decision),priorityScore:evaluation.priorityScore,hits:evaluation.hits,risk:computedRisk,route:evaluation.route};setInvoiceState(v=>[...generated,...v]);setReimbursements(v=>existing&&existing.workflowStatus!=='REJECTED'?v.map(x=>x.id===existing.id?claim:x):[claim,...v]);setAudits(v=>[{id:`A${Date.now()}`,tenantId:TENANT_ID,reimbursementId:id,time:new Date().toLocaleString('zh-CN',{hour12:false}),aiResult:evaluation.decision,manualResult:'—',risk:computedRisk,reviewer:'系统',note:data.resubmissionOf?'员工已提交修改后的新申请':'员工提交报销申请',action:'EMPLOYEE_SUBMIT',beforeStatus:existing?.workflowStatus,afterStatus:claim.workflowStatus,ruleSetVersion:evaluation.ruleSetVersion,traceId:evaluation.traceId},...v]);notify(claim.workflowStatus==='APPROVED'?'审核通过，已进入付款流程':'已提交财务审核');};
  const withdrawEmployeeClaim=(id:string)=>{if(!sessionUser)return;try{const claim=reimbursements.find(x=>x.id===id);if(!claim||!AuthService.canAccessClaim(sessionUser,claim))throw new DomainError('FORBIDDEN','不能操作该申请');const updated=WorkflowStateMachine.transition(claim,'CANCELLED');setReimbursements(v=>v.map(x=>x.id===id?updated:x));notify('申请已撤回')}catch(error){notify(error instanceof Error?error.message:'撤回失败')}};
  const logout=()=>{AuthService.logout();setSessionUser(null);location.hash=''};
  if(!sessionUser)return <LoginPage onLogin={setSessionUser}/>;
  if(sessionUser.role==='EMPLOYEE')return <EmployeePortal user={sessionUser} reimbursements={reimbursements} budgets={budgetState} onSave={saveEmployeeClaim} onSubmit={submitEmployeeClaim} onWithdraw={withdrawEmployeeClaim} onLogout={logout}/>;
  return <div className="app">
    <aside className={`sidebar ${collapsed?'collapsed':''}`}>
      <div className="brand"><div className="brandmark"><ShieldCheck/></div>{!collapsed&&<div><b>衡策</b><span>FINWISE</span></div>}<button className="collapse" onClick={()=>setCollapsed(!collapsed)}><PanelLeftClose/></button></div>
      <nav>{nav.map((n)=><div key={n.name}>{n.group&&!collapsed&&<div className="navgroup">{n.group}</div>}<button className={page===n.name?'active':''} onClick={()=>navigate(n.name)} title={n.name}><n.icon/>{!collapsed&&<span>{n.name}</span>}{n.name==='报销审核'&&!collapsed&&<em>{reimbursements.filter(r=>['WAITING_MANUAL_REVIEW','SUSPENDED','WAITING_SUPPLEMENT'].includes(r.workflowStatus)).length}</em>}</button></div>)}</nav>
      <div className="system-health"><i/>{!collapsed&&<span>决策服务运行正常<small>规则库更新于 10:24</small></span>}</div>
    </aside>
    <main>
      <header><div className="company"><div className="company-logo">星</div><div><span>当前公司</span><b>{company}</b></div><ChevronDown/></div><div className="header-actions"><div className="global-search"><Search/><input placeholder="搜索报销单、发票或员工"/><kbd>⌘ K</kbd></div><button><HelpCircle/></button><button className="bell"><Bell/><i/></button><button className="user" onClick={logout} title="退出登录"><span>{sessionUser.name.slice(0,1)}</span><div><b>{sessionUser.name}</b><small>财务负责人 · 退出</small></div><ChevronDown/></button></div></header>
      <div className="content">
        {page==='工作台'&&<Dashboard reimbursements={reimbursements} openAudit={openAudit} notify={notify}/>} 
        {page==='报销审核'&&<AuditWorkspace reimbursements={reimbursements} selectedId={selectedId} setSelectedId={setSelectedId} updateDecision={updateDecision} onRecheck={reevaluate} onClaim={claimTask} onRelease={releaseTask} onTransfer={transferTask} onSettle={settlePayment} onRetryPayment={retryPayment} notify={notify} currentUser={sessionUser} invoiceById={id=>invoiceState.find(x=>x.id===id)}/>} 
        {page==='发票中心'&&<InvoiceCenter notify={notify} invoiceState={invoiceState} reimbursements={reimbursements}/>} 
        {page==='风险中心'&&<RiskCenter reimbursements={reimbursements} openAudit={openAudit}/>} 
        {page==='预算管理'&&<BudgetPage notify={notify} budgets={budgetState}/>} 
        {page==='规则引擎'&&<RulePage rules={rules} setRules={setRules} notify={notify}/>} 
        {page==='员工管理'&&<EmployeePage/>} 
        {page==='供应商管理'&&<SupplierPage/>} 
        {page==='审核记录'&&<AuditLog audits={audits} openAudit={openAudit}/>} 
        {page==='系统设置'&&<SettingsPage notify={notify}/>} 
      </div>
    </main>
    {toast&&<div className="toast"><CheckCircle2/>{toast}</div>}
  </div>
}

function PageHead({eyebrow,title,desc,actions}:{eyebrow?:string,title:string,desc:string,actions?:any}){return <div className="pagehead"><div>{eyebrow&&<span>{eyebrow}</span>}<h1>{title}</h1><p>{desc}</p></div>{actions&&<div className="pageactions">{actions}</div>}</div>}

function Dashboard({reimbursements,openAudit,notify}:{reimbursements:Reimbursement[],openAudit:(s:string)=>void,notify:(s:string)=>void}){
  const metrics=useMemo(()=>({total:reimbursements.length,pending:reimbursements.filter(r=>['SUBMITTED','AUDITING'].includes(r.workflowStatus)).length,auto:reimbursements.filter(r=>r.machineDecision==='自动通过').length,manual:reimbursements.filter(r=>r.workflowStatus==='WAITING_MANUAL_REVIEW').length,rejected:reimbursements.filter(r=>r.workflowStatus==='REJECTED').length,suspended:reimbursements.filter(r=>r.workflowStatus==='SUSPENDED').length,highRisk:reimbursements.filter(r=>r.risk==='高').length,blockedAmount:reimbursements.filter(r=>r.workflowStatus==='REJECTED').reduce((n,r)=>n+r.amount,0),autoAmount:reimbursements.filter(r=>r.machineDecision==='自动通过').reduce((n,r)=>n+r.amount,0)}),[reimbursements]);
  return <>
    <PageHead eyebrow="2026年9月7日 · 星期一" title="早上好，王敏" desc="审核引擎已完成今晨批次，12 笔报销需要你的关注。" actions={<><button className="secondary" onClick={()=>notify('日报导出任务已创建')}><Download/>导出日报</button><button className="primary" onClick={()=>openAudit('BX202609070005')}><FileCheck2/>开始审核</button></>}/>
    <section className="decision-strip"><div className="decision-title"><div><Sparkles/></div><span>当前智能决策</span><b>{metrics.total}</b><small>笔报销</small></div>{[['待审核',metrics.pending,'待处理'],['自动通过',metrics.auto,`${Math.round(metrics.auto/metrics.total*100)}%`],['人工复核',metrics.manual,'需关注'],['驳回',metrics.rejected,'已拦截'],['挂起',metrics.suspended,'待处理']].map(x=><div className={`decision-item d-${x[0]}`} key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</section>
    <div className="dash-grid">
      <section className="panel risk-overview"><div className="panel-head"><div><h2>财务风险</h2><p>基于当前数据实时聚合</p></div><button className="text-btn">查看风险中心 <ChevronRight/></button></div><div className="big-risk"><div className="risk-ring"><strong>{metrics.highRisk}</strong><span>高风险事件</span></div><div><b>需优先处理</b><p>数据随审核结果实时更新</p></div><span className="trend-good">实时</span></div><div className="risk-metrics">{[['异常发票',reimbursements.filter(r=>r.risk==='高').length],['重复发票',reimbursements.filter(r=>r.hits.some(h=>h.id==='RULE-004')).length],['黑名单命中',reimbursements.filter(r=>r.hits.some(h=>h.id==='RULE-008')).length],['超预算',reimbursements.filter(r=>r.hits.some(h=>h.id==='RULE-003')).length],['高风险员工',new Set(reimbursements.filter(r=>r.risk==='高').map(r=>r.employeeId)).size]].map(x=><div key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div></section>
      <section className="panel efficiency"><div className="panel-head"><div><h2>审核效率</h2><p>当前演示数据</p></div><button className="iconbtn" aria-label="更多审核效率选项"><MoreHorizontal/></button></div><div className="eff-top"><div className="score-ring"><strong>{Math.round(metrics.auto/metrics.total*100)}<small>%</small></strong><span>自动审核率</span></div><div className="eff-stats"><div><span>人工审核率</span><b>{Math.round(metrics.manual/metrics.total*100)}%</b></div><div><span>平均审核时间</span><b>42<small> 秒</small></b></div><div><span>累计审核</span><b>{metrics.total}<small> 笔</small></b></div></div></div><div className="money-stats"><div><span>自动通过金额</span><b>{money(metrics.autoAmount)}</b></div><div><span>风险拦截金额</span><b>{money(metrics.blockedAmount)}</b></div></div></section>
    </div>
    <section className="panel queue"><div className="panel-head"><div><h2>优先处理队列</h2><p>基于风险等级、金额和提交时间智能排序</p></div><div className="tabs"><button className="active">全部 <em>{metrics.total}</em></button><button>高风险 {metrics.highRisk}</button><button>人工复核 {metrics.manual}</button></div></div><table><thead><tr><th>报销单号</th><th>员工</th><th>报销金额</th><th>费用科目</th><th>风险等级</th><th>命中规则</th><th>流程状态</th><th></th></tr></thead><tbody>{reimbursements.slice(0,5).map(r=><tr key={r.id} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&openAudit(r.id)} onClick={()=>openAudit(r.id)}><td><b className="mono">{r.id}</b><small>{r.submittedAt}</small></td><td><div className="employee"><span>{emp(r.employeeId).avatar}</span><div><b>{emp(r.employeeId).name}</b><small>{emp(r.employeeId).department}</small></div></div></td><td><strong>{money(r.amount)}</strong></td><td>{r.category}</td><td><Risk value={r.risk}/></td><td>{r.hits.length?<div className="rule-chips">{r.hits.slice(0,2).map(h=><span key={`${h.id}-${h.version}`}>{h.id} v{h.version}</span>)}</div>:<span className="muted">—</span>}</td><td><Status value={workflowLabel(r.workflowStatus)}/></td><td><ChevronRight className="row-arrow"/></td></tr>)}</tbody></table><div className="table-foot"><span>显示 {Math.min(5,metrics.total)} 条，共 {metrics.total} 条</span><button onClick={()=>location.hash='#audit'}>查看全部待处理 <ArrowLeft className="flip"/></button></div></section>
    <div className="pipeline"><span>智能审核链路</span>{['票据识别','发票验真','规则审核','风险评分','决策路由','人工反馈'].map((x,i)=><div key={x}><i>{i+1}</i>{x}{i<5&&<ChevronRight/>}</div>)}</div>
  </>
}

function AuditWorkspace({reimbursements,selectedId,setSelectedId,updateDecision,onRecheck,onClaim,onRelease,onTransfer,onSettle,onRetryPayment,notify,currentUser,invoiceById}:{reimbursements:Reimbursement[],selectedId:string,setSelectedId:(s:string)=>void,updateDecision:(id:string,d:Decision,n:string)=>void,onRecheck:(id:string)=>{hits:unknown[]},onClaim:(id:string)=>void,onRelease:(id:string)=>void,onTransfer:(id:string,target:string)=>void,onSettle:(id:string,success:boolean)=>void,onRetryPayment:(id:string)=>void,notify:(s:string)=>void,currentUser:SessionUser,invoiceById:(id:string)=>Invoice|undefined}){
  const r=reimbursements.find(x=>x.id===selectedId) || reimbursements[0]; const e=emp(r.employeeId); const inv=invoiceById(r.invoiceId)||invoice(r.invoiceId);
  const [query,setQuery]=useState(''); const [filter,setFilter]=useState('全部'); const [evidence,setEvidence]=useState<string|null>(r.hits[0]?.id||null); const [modal,setModal]=useState<Decision|null>(null); const [note,setNote]=useState(''); const [tab,setTab]=useState('报销详情'); const [checking,setChecking]=useState(false);
  const list=reimbursements.filter(x=>(filter==='全部'||claimDecision(x)===filter)&&(x.id.includes(query)||emp(x.employeeId).name.includes(query)));
  const decision=claimDecision(r);const canAct=['WAITING_MANUAL_REVIEW','SUSPENDED','WAITING_SUPPLEMENT','AUDITING'].includes(r.workflowStatus);
  const recheck=()=>{setChecking(true);window.setTimeout(()=>{try{const result=onRecheck(r.id);notify(`复核完成：执行 ${initialRules.length} 条规则，命中 ${result.hits.length} 条`)}catch(error){notify(error instanceof Error?error.message:'重新审核失败')}finally{setChecking(false)}},450)};
  return <div className="audit-page">
    <div className="audit-top"><div><button className="back" onClick={()=>history.back()} aria-label="返回上一页"><ArrowLeft/></button><div><span>报销审核</span><h1>{r.id}</h1></div><Status value={workflowLabel(r.workflowStatus)}/>{TaskAssignmentService.isOverdue(r)&&<span className="overdue-badge"><AlertTriangle/>已超时</span>}</div><div>{r.workflowStatus==='WAITING_MANUAL_REVIEW'&&!r.assignedTo&&<button className="primary" onClick={()=>onClaim(r.id)}><UserCheck/>认领任务</button>}{r.workflowStatus==='WAITING_MANUAL_REVIEW'&&r.assignedTo===currentUser.id&&<><button className="secondary" onClick={()=>onRelease(r.id)}>释放任务</button><button className="secondary" onClick={()=>{const target=window.prompt('请输入接收人账号','U-FIN-002');if(target)onTransfer(r.id,target)}}>转派</button></>}{r.paymentStatus==='QUEUED'&&<><button className="secondary" onClick={()=>onSettle(r.id,false)}>模拟支付失败</button><button className="primary" onClick={()=>onSettle(r.id,true)}><CircleDollarSign/>完成支付</button></>}{r.paymentStatus==='FAILED'&&<button className="primary" onClick={()=>onRetryPayment(r.id)}><RefreshCw/>重试支付</button>}<button className="secondary" onClick={recheck} disabled={checking}>{checking?<Loader2 className="spin"/>:<RefreshCw/>}重新执行规则</button><button className="iconbtn" aria-label="更多报销操作"><MoreHorizontal/></button></div></div>
    <div className="audit-layout">
      <aside className="audit-list"><div className="list-title"><h2>待处理报销</h2><span>{list.length}</span></div><div className="list-search"><Search/><input value={query} onChange={x=>setQuery(x.target.value)} placeholder="搜索单号或员工"/><button><ListFilter/></button></div><div className="mini-tabs">{['全部','人工复核','挂起'].map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x}</button>)}</div><div className="claim-list">{list.map(x=><button key={x.id} className={x.id===r.id?'active':''} onClick={()=>{setSelectedId(x.id);setEvidence(x.hits[0]?.id||null)}}><div><span className="avatar">{emp(x.employeeId).avatar}</span><b>{emp(x.employeeId).name}</b><Risk value={x.risk}/></div><strong>{money(x.amount)}</strong><span>{x.category} · {x.submittedAt}</span><small>{x.id}</small></button>)}{!list.length&&<Empty text="没有匹配的报销单"/>}</div></aside>
      <section className="audit-detail"><div className="detail-tabs">{['报销详情','发票信息','审核记录'].map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==='报销详情'?<>
        <div className="section-block"><div className="section-title"><h3>基础信息</h3><button>查看申请单 <ChevronRight/></button></div><div className="info-grid"><Info label="申请员工"><div className="employee"><span>{e.avatar}</span><div><b>{e.name}</b><small>{e.department} · {e.title}</small></div></div></Info><Info label="报销类型" value={r.category}/><Info label="提交时间" value={`2026-09-07 ${r.submittedAt.replace('今天 ','')}`}/><Info label="报销总金额"><strong className="amount">{money(r.amount)}</strong></Info><Info label="所属预算" value={r.budgetName}/><Info label="当前状态"><Status value={workflowLabel(r.workflowStatus)}/></Info></div><div className="purpose"><span>报销事由</span><p>{r.purpose}</p></div></div>
        <InvoiceCard inv={inv}/><div className="section-block"><div className="section-title"><h3>预算占用</h3><span className={r.availableBudget<r.amount?'warning-text':'success-text'}>{r.availableBudget<r.amount?'预算不足':'预算充足'}</span></div><div className="budget-bar"><div><span>可用预算</span><b>{money(r.availableBudget)}</b></div><div><span>本次申请冻结</span><b>{money(r.amount)}</b></div><div><span>审核后可用</span><b className={r.availableBudget-r.amount<0?'red':''}>{money(Math.max(0,r.availableBudget-r.amount))}</b></div></div></div>
      </>:tab==='发票信息'?<InvoiceDetail inv={inv}/>:<MiniAuditLog id={r.id}/>}</section>
      <aside className="ai-panel"><div className="ai-head"><div><Bot/></div><div><span>衡策智能审核</span><small>规则 + 数据 + AI 解释</small></div><span className="live"><i/>分析完成</span></div><div className={`verdict verdict-${decision}`}><span>机器审核结论</span><div><DecisionIcon d={decision}/><strong>{decision==='人工复核'?'建议人工复核':decision}</strong></div><p>{decision==='自动通过'?'验真、规则、预算与员工权限均通过，可进入支付队列。':r.hits.map(h=>h.description).join('；')||'需要财务人员进一步确认。'}</p></div><div className="score-card"><div><span>审核优先级分 <HelpCircle/></span><strong>{r.priorityScore}<small>/100</small></strong></div><div className="scorebar"><i style={{width:`${r.priorityScore}%`}}/></div><p>分数越低，越需要优先人工关注</p></div><div className="ai-section"><div className="ai-section-title"><h3>命中规则</h3><span>{r.hits.length}</span></div>{r.hits.length?r.hits.map(h=><div className={`hit ${evidence===h.id?'open':''}`} key={`${h.id}-${h.version}`}><button onClick={()=>setEvidence(evidence===h.id?null:h.id)} aria-expanded={evidence===h.id}><div><Risk value={h.risk}/><b>{h.name}</b><small>{h.id} v{h.version}</small></div><ChevronDown/></button>{evidence===h.id&&<div className="evidence"><div className="evidence-label"><FileSearch/>审核证据链</div>{h.evidence.map((x,i)=><div className="evidence-step" key={x}><i>{i+1}</i><span>{x}</span></div>)}<div className="evidence-result"><span>规则动作</span><Status value={h.action}/></div></div>}</div>):<div className="all-clear"><ShieldCheck/><b>未命中风险规则</b><span>已启用规则全部通过</span></div>}</div><div className="route"><span>决策路由</span><div><UserCheck/><p><b>{r.route}</b><small>{r.assignedTo?'任务已认领':decision==='人工复核'?'等待认领':'系统实时处理'}</small></p></div></div><div className="audit-actions"><button className="approve" disabled={!canAct} onClick={()=>setModal('自动通过')}><Check/>通过</button><button className="reject" disabled={!canAct} onClick={()=>setModal('驳回')}><X/>驳回</button><button disabled={!canAct} onClick={()=>setModal('挂起')}><Clock3/>挂起</button><button disabled={!canAct} onClick={()=>setModal('要求补充材料')}><UserCheck/>要求补充材料</button></div></aside>
    </div>{modal&&<DecisionModal decision={modal} note={note} setNote={setNote} close={()=>setModal(null)} confirm={()=>{updateDecision(r.id,modal,note||'人工复核处理');setModal(null);setNote('')}}/>}
  </div>
}

function Info({label,value,children}:{label:string,value?:string,children?:any}){return <div className="info"><span>{label}</span>{children||<b>{value}</b>}</div>}
function DecisionIcon({d}:{d:Decision}){return d==='自动通过'?<CheckCircle2/>:d==='驳回'?<XCircle/>:d==='挂起'?<Clock3/>:<UserCheck/>}
function InvoiceCard({inv}:{inv:Invoice}){return <div className="section-block"><div className="section-title"><h3>关联发票</h3><button>查看完整发票 <ChevronRight/></button></div><div className="invoice-card"><div className="invoice-preview"><div className="inv-paper"><span>增值税电子普通发票</span><b>{inv.seller}</b><small>价税合计（小写）</small><strong>{money(inv.total)}</strong><i>票样预览</i></div><span>{inv.source}</span></div><div className="invoice-data"><div className={`verify ${inv.verifyStatus==='VALID'?'ok':'bad'}`}>{inv.verifyStatus==='VALID'?<ShieldCheck/>:<ShieldAlert/>}<div><b>{inv.verifyStatus==='VALID'?'验真通过':'验真异常'}</b><span>{inv.verifyStatus==='VALID'?'税务平台信息匹配':'需要人工核验'}</span></div></div><div className="invoice-fields"><Info label="发票号码" value={inv.number}/><Info label="开票日期" value={inv.date}/><Info label="销售方" value={inv.seller}/><Info label="购买方" value={inv.buyer}/><Info label="项目名称" value={inv.item}/><Info label="价税合计"><strong className="amount">{money(inv.total)}</strong></Info></div><div className="ocr"><Sparkles/>OCR 平均置信度 <b>{inv.ocrConfidence}%</b><span>已结构化识别 9 个字段</span></div></div></div></div>}
function InvoiceDetail({inv}:{inv:Invoice}){return <div className="section-block full-invoice"><div className="invoice-document"><h3>增值税电子普通发票</h3><div className="doc-no">发票代码：{inv.code}<br/>发票号码：{inv.number}<br/>开票日期：{inv.date}</div><div className="party"><p><span>购买方</span><b>{inv.buyer}</b><small>纳税人识别号：{inv.buyerTaxId}</small></p><p><span>销售方</span><b>{inv.seller}</b><small>纳税人识别号：{inv.sellerTaxId}</small></p></div><table><thead><tr><th>项目名称</th><th>金额</th><th>税额</th></tr></thead><tbody><tr><td>{inv.item}</td><td>{money(inv.amount)}</td><td>{money(inv.tax)}</td></tr></tbody></table><div className="doc-total">价税合计 <strong>{money(inv.total)}</strong></div></div></div>}
function MiniAuditLog({id}:{id:string}){return <div className="section-block"><div className="timeline"><div><i><Check/></i><p><b>智能审核已完成</b><span>规则引擎执行完毕 · 命中规则已生成证据链</span><small>今天 09:43 · 系统</small></p></div><div><i><FileSearch/></i><p><b>发票验真完成</b><span>税务平台字段比对完成</span><small>今天 09:42 · 系统</small></p></div><div><i><Upload/></i><p><b>报销单已提交</b><span>{id} 进入智能审核流程</span><small>今天 09:42 · 申请人</small></p></div></div></div>}
function DecisionModal({decision,note,setNote,close,confirm}:{decision:Decision,note:string,setNote:(s:string)=>void,close:()=>void,confirm:()=>void}){useEffect(()=>{const key=(e:KeyboardEvent)=>e.key==='Escape'&&close();window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[close]);return <div className="modal-bg" onMouseDown={close}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="decision-title" onMouseDown={e=>e.stopPropagation()}><div className="modal-icon"><DecisionIcon d={decision}/></div><h2 id="decision-title">确认{decision==='自动通过'?'通过':decision}</h2><p>{decision==='自动通过'?'通过后将进入支付队列，并正式占用预算。':decision==='驳回'?'驳回后将释放冻结预算，并通知申请人。':decision==='要求补充材料'?'申请将进入待补充材料状态，预算保持冻结。':'请填写处理说明，系统会完整记录本次人工决策。'}</p><label htmlFor="decision-note">审核意见 <em>*</em></label><textarea id="decision-note" value={note} onChange={e=>setNote(e.target.value)} placeholder={decision==='驳回'?'请输入驳回原因及修改建议':'请输入本次审核说明'} autoFocus/><div className="modal-actions"><button onClick={close}>取消</button><button className="primary" disabled={!note.trim()} onClick={confirm}>确认{decision==='自动通过'?'通过':decision}</button></div></div></div>}

function InvoiceCenter({notify,invoiceState,reimbursements}:{notify:(s:string)=>void;invoiceState:Invoice[];reimbursements:Reimbursement[]}){
  const file=useRef<HTMLInputElement>(null); const [upload,setUpload]=useState(false); const [ocr,setOcr]=useState<Invoice|null>(null); const [verify,setVerify]=useState<string>(''); const [error,setError]=useState('');
  const [query,setQuery]=useState('');const [verifyFilter,setVerifyFilter]=useState('ALL');const [page,setPage]=useState(1);const pageSize=10;const filtered=invoiceState.filter(i=>(verifyFilter==='ALL'||i.verifyStatus===verifyFilter)&&[i.number,i.code,i.seller,i.buyer].some(v=>v.toLowerCase().includes(query.toLowerCase())));const pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));const rows=filtered.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[query,verifyFilter]);const exportInvoices=()=>downloadCsv('发票明细.csv',['发票号码','代码','销售方','购买方','金额','日期','验真状态'],filtered.map(i=>[i.number,i.code,i.seller,i.buyer,i.total,i.date,i.verifyStatus]));
  const choose=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;setUpload(true);setOcr(null);setVerify('');setError('');try{const result=await OcrService.recognize(f);setOcr(OcrService.toInvoice(result))}catch(err){const message=err instanceof Error?err.message:'OCR 服务异常';setError(message);notify(message)}finally{setUpload(false);e.target.value=''}};
  const doVerify=async()=>{if(!ocr)return;setVerify('loading');setError('');try{const result=await InvoiceVerificationService.verifyInvoice(ocr);setVerify(result.message);setOcr({...ocr,verifyStatus:result.status,verificationMessage:result.message});notify(result.message)}catch(err){const message=err instanceof Error?err.message:'验真服务异常';setError(`${message}，已降级为人工复核`);setVerify('');notify(`${message}，已降级为人工复核`)} };
  return <><PageHead eyebrow="票据全生命周期管理" title="发票中心" desc="统一接入、识别、验真与查重，每一张票据都有可追溯状态。" actions={<><button className="secondary" onClick={exportInvoices}><Download/>导出</button><button className="primary" onClick={()=>file.current?.click()}><Upload/>上传发票</button><input ref={file} onChange={choose} hidden type="file" accept="image/jpeg,image/png,image/webp,application/pdf" aria-label="选择发票文件"/></>}/>
  {upload&&<div className="process-banner" role="status" aria-live="polite"><Loader2 className="spin"/><div><b>正在识别发票</b><span>OCR 服务正在提取关键字段...</span></div><div className="progress"><i/></div></div>}{error&&<div className="error-banner" role="alert"><AlertTriangle/>{error}<button onClick={()=>file.current?.click()}>重新上传</button></div>}
  {ocr&&<div className="upload-result"><div className="result-file"><div><Receipt/></div><p><b>{ocr.source}</b><span>OCR 识别完成 · 置信度 {ocr.ocrConfidence}%</span></p><Status value="识别成功"/></div><div className="result-fields"><Info label="发票号码" value={ocr.number}/><Info label="销售方" value={ocr.seller}/><Info label="购买方" value={ocr.buyer}/><Info label="价税合计"><strong>{money(ocr.total||0)}</strong></Info></div><div className="result-action">{verify&&verify!=='loading'?<span className="verified"><ShieldCheck/>{verify}</span>:<button className="primary" onClick={doVerify} disabled={verify==='loading'}>{verify==='loading'?<Loader2 className="spin"/>:<ShieldCheck/>}{verify==='loading'?'正在连接税务平台':'立即验真'}</button>}<button onClick={()=>{setOcr(null);notify('已创建报销草稿')}}>创建报销单 <ChevronRight/></button></div></div>}
  <div className="stat-row">{[['全部发票',invoiceState.length,`本月新增 ${invoiceState.length}`],['验真通过',invoiceState.filter(i=>i.verifyStatus==='VALID').length,`${Math.round(invoiceState.filter(i=>i.verifyStatus==='VALID').length/Math.max(1,invoiceState.length)*100)}%`],['异常发票',invoiceState.filter(i=>i.verifyStatus!=='VALID').length,'需关注'],['待验真',invoiceState.filter(i=>i.verifyStatus==='PENDING').length,'等待处理']].map((x,i)=><div className="stat-card" key={x[0]}><div className={`stat-icon s${i}`}><Receipt/></div><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</div>
  <section className="panel data-panel"><div className="toolbar"><div className="searchbox"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索发票号码、销售方或购买方" aria-label="搜索发票"/></div><select value={verifyFilter} onChange={e=>setVerifyFilter(e.target.value)} aria-label="验真状态筛选"><option value="ALL">全部验真状态</option><option value="VALID">验真通过</option><option value="VOIDED">已作废</option><option value="NOT_FOUND">未查询到</option></select><span/><button onClick={()=>{setQuery('');setVerifyFilter('ALL')}}><RefreshCw/>重置</button></div><table><thead><tr><th>发票号码 / 代码</th><th>销售方</th><th>购买方</th><th>金额</th><th>开票日期</th><th>验真状态</th><th>报销状态</th><th>风险</th><th></th></tr></thead><tbody>{rows.map((i)=><tr key={i.id}><td><b className="mono">{i.number}</b><small>{i.code}</small></td><td>{i.seller}</td><td className={i.buyer!==company?'red-text':''}>{i.buyer}</td><td><strong>{money(i.total)}</strong></td><td>{i.date}</td><td><span className={i.verifyStatus==='VALID'?'verify-ok':'verify-bad'}>{i.verifyStatus==='VALID'?<CheckCircle2/>:<XCircle/>}{i.verifyStatus==='VALID'?'验真通过':i.verifyStatus==='VOIDED'?'已作废':'验真异常'}</span></td><td><Status value={reimbursements.some(r=>(r.invoiceIds||[r.invoiceId]).includes(i.id))?'已报销':'未报销'}/></td><td><Risk value={i.buyer!==company||i.verifyStatus!=='VALID'?'高':'低'}/></td><td><button className="iconbtn" aria-label="发票更多操作"><MoreHorizontal/></button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="没有符合筛选条件的发票"/>}<div className="pagination"><span>共 {filtered.length} 张发票 · 第 {page}/{pageCount} 页</span><div><button disabled={page===1} onClick={()=>setPage(p=>p-1)}>上一页</button>{Array.from({length:pageCount},(_,i)=><button key={i} className={page===i+1?'active':''} onClick={()=>setPage(i+1)}>{i+1}</button>)}<button disabled={page===pageCount} onClick={()=>setPage(p=>p+1)}>下一页</button></div></div></section></> 
}

function RiskCenter({reimbursements,openAudit}:{reimbursements:Reimbursement[],openAudit:(s:string)=>void}){
  const events=[{type:'重复发票',count:8,amount:28460,icon:RefreshCw,color:'red'},{type:'黑名单供应商',count:3,amount:45600,icon:ShieldAlert,color:'purple'},{type:'超预算',count:14,amount:92350,icon:WalletCards,color:'orange'},{type:'大额异常',count:9,amount:186400,icon:CircleDollarSign,color:'blue'},{type:'购买方错误',count:6,amount:18320,icon:Building2,color:'pink'}];
  const highRisk=reimbursements.filter(r=>r.risk==='高');const riskAmount=highRisk.reduce((n,r)=>n+r.amount,0);const exportRisk=()=>downloadCsv('风险事件报告.csv',['报销编号','员工','风险等级','命中规则','金额','流程状态'],highRisk.map(r=>[r.id,emp(r.employeeId).name,r.risk,r.hits.map(h=>h.name).join('、'),r.amount,workflowLabel(r.workflowStatus)]));
  return <><PageHead eyebrow="异常驾驶舱" title="风险中心" desc="从事件、人员、供应商和规则四个维度，集中洞察财务异常。" actions={<button className="secondary" onClick={exportRisk}><Download/>导出风险报告</button>}/><div className="risk-hero"><div><span>当前风险拦截金额</span><strong>{money(riskAmount)}</strong><p><b>实时聚合</b> 来自 {highRisk.length} 笔高风险报销</p></div><div className="risk-chart">{[35,58,42,68,50,77,61,84,56,73,48,67,82,60,75,45,66,79,54,87,63,73,57,69].map((x,i)=><i key={i} style={{height:`${x}%`}} className={i>19?'hot':''}/>)}</div><div className="risk-summary"><div><b>{highRisk.length}</b><span>异常事件</span></div><div><b>{highRisk.filter(r=>r.hits.some(h=>h.blocking)).length}</b><span>阻断事件</span></div><div><b>{reimbursements.filter(r=>['REJECTED','APPROVED','PAID'].includes(r.workflowStatus)).length}</b><span>已处置</span></div></div></div><div className="event-grid">{events.map(e=><div className="event-card" key={e.type}><div className={`event-icon ${e.color}`}><e.icon/></div><p><span>{e.type}</span><b>{e.count}<small> 件</small></b></p><div><span>涉及金额</span><strong>{money(e.amount)}</strong></div><button onClick={()=>{const target=highRisk.find(r=>r.hits.some(h=>h.name===e.type));if(target)openAudit(target.id)}}>查看事件 <ChevronRight/></button></div>)}</div><div className="split-grid"><section className="panel"><div className="panel-head"><div><h2>高风险事件</h2><p>按风险优先级实时排序</p></div><button className="text-btn">查看全部</button></div><div className="risk-list">{highRisk.slice(0,5).map(r=><button onClick={()=>openAudit(r.id)} key={r.id}><div className="risk-badge"><AlertTriangle/></div><p><b>{r.hits[0]?.name||'异常报销'}</b><span>{r.id} · {emp(r.employeeId).name}</span></p><strong>{money(r.amount)}</strong><Risk value="高"/><ChevronRight/></button>)}</div></section><section className="panel"><div className="panel-head"><div><h2>风险来源分布</h2><p>当前报销数据</p></div><button className="iconbtn"><MoreHorizontal/></button></div><div className="donut-wrap"><div className="donut"><div><b>{highRisk.length}</b><span>风险事件</span></div></div><div className="legend">{[['规则策略',highRisk.filter(r=>r.hits.length).length],['发票异常',highRisk.filter(r=>r.hits.some(h=>h.id==='RULE-001')).length],['预算风险',highRisk.filter(r=>r.hits.some(h=>h.id==='RULE-003')).length],['其他',highRisk.filter(r=>!r.hits.length).length]].map((x,i)=><div key={x[0]}><i className={`l${i}`}/><span>{x[0]}</span><b>{x[1]}</b></div>)}</div></div><div className="insight"><Sparkles/><p><b>智能洞察</b><span>高风险事件已与规则版本、发票指纹和人工处理结果建立追溯关系。</span></p></div></section></div></>
}

function BudgetPage({notify,budgets}:{notify:(s:string)=>void,budgets:Budget[]}){const totals=budgets.reduce((a,b)=>({total:a.total+b.total,spent:a.spent+b.spent,frozen:a.frozen+b.frozen}),{total:0,spent:0,frozen:0});const exportCsv=()=>downloadCsv('预算明细.csv',['预算名称','类型','负责人','总预算','实际支出','冻结金额','可用预算'],budgets.map(b=>[b.name,b.type,b.owner,b.total,b.spent,b.frozen,b.total-b.spent-b.frozen]));return <><PageHead eyebrow="预算控制与占用" title="预算管理" desc="提交时冻结、通过后扣减、驳回时释放，避免并发报销造成超支。" actions={<button className="primary" onClick={()=>notify('已创建预算草稿')}><Plus/>新建预算</button>}/><div className="stat-row"><div className="stat-card"><span>预算总额</span><strong>{money(totals.total)}</strong><small>来自 {budgets.length} 个预算池</small></div><div className="stat-card"><span>实际支出</span><strong>{money(totals.spent)}</strong><small>已完成付款</small></div><div className="stat-card"><span>审批中冻结</span><strong>{money(totals.frozen)}</strong><small>通过或驳回后自动结转</small></div><div className="stat-card"><span>可用预算</span><strong>{money(totals.total-totals.spent-totals.frozen)}</strong><small>{Math.round((totals.total-totals.spent-totals.frozen)/totals.total*100)}% 可用</small></div></div><div className="budget-flow"><div><Upload/><b>提交报销</b><span>发起预算校验</span></div><ChevronRight/><div className="active"><LockKeyhole/><b>冻结预算</b><span>不计入实际支出</span></div><ChevronRight/><div><FileCheck2/><b>审批通过</b><span>进入支付队列</span></div><ChevronRight/><div><CircleDollarSign/><b>正式扣减</b><span>付款后计入支出</span></div><p><XCircle/>驳回后自动释放冻结额度</p></div><section className="panel data-panel"><div className="toolbar"><div className="searchbox"><Search/><input placeholder="搜索预算名称或归属部门"/></div><button><ListFilter/>预算类型 <ChevronDown/></button><button>预算周期 <ChevronDown/></button><span/><button onClick={exportCsv}><Download/>导出</button></div><table><thead><tr><th>预算名称</th><th>类型</th><th>负责人</th><th>总预算</th><th>实际支出</th><th>冻结金额</th><th>可用预算</th><th>执行进度</th><th>状态</th></tr></thead><tbody>{budgets.map(b=>{const available=b.total-b.spent-b.frozen;const pct=Math.round((b.spent+b.frozen)/b.total*100);return <tr key={b.id}><td><b>{b.name}</b><small>{b.id}</small></td><td>{b.type}</td><td>{b.owner}</td><td>{money(b.total)}</td><td>{money(b.spent)}</td><td>{money(b.frozen)}</td><td><strong className={available/b.total<.1?'red-text':''}>{money(available)}</strong></td><td><div className="inline-progress"><i style={{width:`${pct}%`}} className={pct>90?'danger':''}/><span>{pct}%</span></div></td><td><Status value={pct>90?'预警':'正常'}/></td></tr>})}</tbody></table></section></>}

function RulePage({rules,setRules,notify}:{rules:Rule[],setRules:(r:Rule[])=>void,notify:(s:string)=>void}){const [editor,setEditor]=useState(false);const [field,setField]=useState('金额');const [op,setOp]=useState('>');const [val,setVal]=useState('5000');const [ruleName,setRuleName]=useState('');const [action,setAction]=useState<Decision>('人工复核');const toggle=(id:string)=>{setRules(rules.map(r=>r.id===id?{...r,enabled:!r.enabled,version:r.version+1}:r));notify('规则状态已更新并生成新版本')};const fieldMap:Record<string,RuleField>={金额:'claim.amount',科目:'claim.category',供应商:'supplier.riskLevel',预算:'budget.available',购买方:'invoice.buyerName'};const opMap:Record<string,RuleOperator>={'>':'GT','<':'LT','=':'EQ','>=':'GTE','<=':'LTE','!=':'NEQ',contains:'CONTAINS'};const createRule=()=>{if(!ruleName.trim()){notify('请填写规则名称');return}const parsed=isNaN(Number(val))?val:Number(val);const id=`RULE-${String(rules.length+1).padStart(3,'0')}`;const next:Rule={id,tenantId:TENANT_ID,version:1,name:ruleName,type:'自定义规则',condition:`${field} ${op} ${typeof parsed==='string'?`“${parsed}”`:parsed}`,ast:{combinator:'AND',conditions:[{field:fieldMap[field]||'claim.amount',operator:opMap[op]||'EQ',value:parsed}]},risk:'中',action,priority:80,blocking:action==='驳回'||action==='挂起',enabled:true,lifecycle:'PUBLISHED',rolloutPercentage:100,effectiveFrom:new Date().toISOString()};setRules([...rules,next]);setEditor(false);setRuleName('');notify(`规则 ${id} 已通过校验并发布 v1`)};const replay=()=>notify(`样本回放完成：${rules.length} 条规则 × ${initialReimbursements.length} 个样本，无执行异常`);return <><PageHead eyebrow="决策底线与自动化策略" title="规则引擎" desc="规则决定底线，数据支撑判断，AI 负责解释，人工负责兜底。" actions={<button className="primary" onClick={()=>setEditor(true)}><Plus/>创建规则</button>}/><div className="rule-summary"><div><Gauge/><p><b>规则运行概况</b><span>规则集已版本化 · AST 安全执行</span></p><strong>{rules.filter(r=>r.enabled).length}<small> 已启用</small></strong></div>{[['发布规则',String(rules.filter(r=>r.lifecycle==='PUBLISHED').length)],['最高版本',`v${Math.max(...rules.map(r=>r.version))}`],['灰度覆盖','100%'],['待优化规则','3']].map(x=><div key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div><section className="panel data-panel"><div className="toolbar"><div className="searchbox"><Search/><input placeholder="搜索规则名称、编号或类型"/></div><button><ListFilter/>规则类型 <ChevronDown/></button><button>执行动作 <ChevronDown/></button><span/><button onClick={replay}><Activity/>样本回放</button></div><table><thead><tr><th>优先级</th><th>规则名称</th><th>规则类型</th><th>条件表达式</th><th>风险等级</th><th>执行动作</th><th>状态</th><th></th></tr></thead><tbody>{rules.map(r=><tr key={r.id}><td><span className="priority">{r.priority}</span></td><td><b>{r.name}</b><small>{r.id} · v{r.version} · {r.lifecycle}</small></td><td>{r.type}</td><td><code>{r.condition}</code></td><td><Risk value={r.risk}/></td><td><Status value={r.action}/></td><td><button aria-label={`${r.enabled?'停用':'启用'} ${r.name}`} onClick={()=>toggle(r.id)} className={`switch ${r.enabled?'on':''}`}><i/></button></td><td><button className="iconbtn" aria-label="规则更多操作"><MoreHorizontal/></button></td></tr>)}</tbody></table></section><div className="feedback"><div><Sparkles/></div><p><b>规则优化建议</b><span>人工推翻的审核结果将保留规则版本与输入快照，可用于离线回放和阈值优化。</span></p><button onClick={replay}>查看差异样本 <ChevronRight/></button></div>{editor&&<div className="modal-bg" onMouseDown={()=>setEditor(false)}><div className="rule-editor" role="dialog" aria-modal="true" aria-labelledby="rule-editor-title" onMouseDown={e=>e.stopPropagation()}><div className="editor-head"><div><h2 id="rule-editor-title">创建审核规则</h2><p>使用可视化条件生成受限 AST，不执行任意代码</p></div><button aria-label="关闭规则编辑器" onClick={()=>setEditor(false)}><X/></button></div><div className="form-grid"><label>规则名称<input value={ruleName} onChange={e=>setRuleName(e.target.value)} placeholder="例如：大额交通费报销" autoFocus/></label><label>规则类型<select><option>发票金额</option><option>公司政策</option><option>预算</option></select></label></div><label>当满足以下条件</label><div className="condition-row"><select value={field} onChange={e=>setField(e.target.value)}><option>金额</option><option>科目</option><option>购买方</option><option>供应商</option><option>预算</option></select><select value={op} onChange={e=>setOp(e.target.value)}><option>&gt;</option><option>&lt;</option><option>=</option><option>&gt;=</option><option>&lt;=</option><option>!=</option><option>contains</option></select><input value={val} onChange={e=>setVal(e.target.value)}/><button aria-label="删除条件"><X/></button></div><button className="add-condition"><Plus/>添加条件</button><div className="expression"><span>系统生成的规则表达式</span><code>{field} {op} {isNaN(Number(val))?`“${val}”`:val}</code></div><div className="form-grid triple"><label>风险等级<select><option>中</option><option>高</option><option>低</option></select></label><label>执行动作<select value={action} onChange={e=>setAction(e.target.value as Decision)}><option>人工复核</option><option>驳回</option><option>挂起</option><option>升级审批</option></select></label><label>优先级<input type="number" defaultValue="80" min="1" max="100"/></label></div><div className="modal-actions"><button onClick={()=>setEditor(false)}>取消</button><button className="secondary" onClick={()=>notify('规则草稿已保存')}>保存草稿</button><button className="primary" onClick={createRule}>校验并发布</button></div></div></div>}</>}

function EmployeePage(){return <><PageHead eyebrow="组织与报销信用" title="员工管理" desc="员工权限、历史行为与信用等级共同参与每一次风险决策。" actions={<button className="primary"><Plus/>添加员工</button>}/><div className="credit-banner"><div><UserCheck/></div><p><b>员工信用模型</b><span>基于历史报销次数、驳回、异常、重复报销与平均金额动态计算</span></p><div className="grade"><i>A</i> 90—100</div><div className="grade"><i>B</i> 70—89</div><div className="grade"><i>C</i> 0—69</div></div><section className="panel data-panel"><div className="toolbar"><div className="searchbox"><Search/><input placeholder="搜索员工姓名、部门或工号"/></div><button><ListFilter/>所属部门 <ChevronDown/></button><button>信用等级 <ChevronDown/></button><span/><button><Download/>导出</button></div><table><thead><tr><th>员工</th><th>部门 / 职级</th><th>历史报销</th><th>历史驳回</th><th>异常次数</th><th>平均金额</th><th>信用分</th><th>信用等级</th><th></th></tr></thead><tbody>{employees.map((e,i)=><tr key={e.id}><td><div className="employee"><span>{e.avatar}</span><div><b>{e.name}</b><small>{e.id}</small></div></div></td><td><b>{e.department}</b><small>{e.title}</small></td><td>{e.historyCount} 次</td><td>{e.rejectedCount} 次</td><td className={e.abnormalCount>4?'red-text':''}>{e.abnormalCount} 次</td><td>{money([680,1280,2360,890,3180][i%5])}</td><td><div className="credit-score"><strong>{e.creditScore}</strong><div><i style={{width:`${e.creditScore}%`}}/></div></div></td><td><span className={`credit c${e.creditLevel}`}>{e.creditLevel}</span></td><td><button className="iconbtn"><MoreHorizontal/></button></td></tr>)}</tbody></table></section></>}

function SupplierPage(){return <><PageHead eyebrow="供应商准入与黑名单" title="供应商管理" desc="结合税务信息、交易历史与异常行为，持续监测供应商风险。" actions={<button className="primary"><Plus/>添加供应商</button>}/><div className="stat-row"><div className="stat-card"><span>供应商总数</span><strong>248</strong><small>本月新增 12</small></div><div className="stat-card"><span>已完成认证</span><strong>226</strong><small>认证率 91.1%</small></div><div className="stat-card"><span>高风险供应商</span><strong>7</strong><small>本月新增 2</small></div><div className="stat-card"><span>黑名单</span><strong>3</strong><small>全部处于监控中</small></div></div><div className="subhead"><div><h2>供应商黑名单</h2><p>命中后自动提升风险等级并进入人工复核或驳回</p></div><button className="secondary"><Plus/>加入黑名单</button></div><section className="panel data-panel"><table><thead><tr><th>供应商名称</th><th>统一社会信用代码</th><th>风险原因</th><th>风险等级</th><th>加入时间</th><th>状态</th><th></th></tr></thead><tbody>{blacklist.map(x=><tr key={x.taxId}><td><div className="supplier"><Building2/><b>{x.name}</b></div></td><td><code>{x.taxId}</code></td><td>{x.reason}</td><td><Risk value={x.risk as RiskLevel}/></td><td>{x.date}</td><td><Status value={x.status}/></td><td><button className="iconbtn"><MoreHorizontal/></button></td></tr>)}</tbody></table></section><div className="keyword-card"><div><h2>风险关键词库</h2><p>票面项目或报销备注命中后，自动进入风险审核</p></div><div>{['礼品卡','高尔夫','娱乐','私人消费','奢侈品'].map(x=><span key={x}>{x}<X/></span>)}<button><Plus/>添加关键词</button></div></div></>}

function AuditLog({audits,openAudit}:{audits:AuditRecord[],openAudit:(s:string)=>void}){const [query,setQuery]=useState('');const [result,setResult]=useState('ALL');const [risk,setRisk]=useState('ALL');const [page,setPage]=useState(1);const pageSize=8;const filtered=audits.filter(a=> (result==='ALL'||a.manualResult===result||a.aiResult===result)&&(risk==='ALL'||a.risk===risk)&&[a.reimbursementId,a.reviewer,a.note].some(v=>v.toLowerCase().includes(query.toLowerCase())));const pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));const rows=filtered.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[query,result,risk]);const exportAudits=()=>downloadCsv('审核日志.csv',['报销编号','审核时间','AI结果','人工结果','风险等级','审核人','备注'],filtered.map(a=>[a.reimbursementId,a.time,a.aiResult,a.manualResult,a.risk,a.reviewer,a.note]));return <><PageHead eyebrow="完整、可信、可追溯" title="审核记录" desc="记录机器决策与人工复核的每一步，并沉淀为规则优化数据。" actions={<button className="secondary" onClick={exportAudits}><Download/>导出审核日志</button>}/><div className="feedback-stats"><div><span>当前记录</span><b>{audits.length}</b></div><div><span>AI 与人工一致率</span><b>{audits.length?Math.round(audits.filter(a=>a.manualResult==='—'||a.manualResult===a.aiResult).length/audits.length*100):0}%</b></div><div className="warn"><span>决策不一致</span><b>{audits.filter(a=>a.manualResult!=='—'&&a.manualResult!==a.aiResult).length}</b></div><div><span>规则版本可追溯</span><b>100%</b></div></div><section className="panel data-panel"><div className="toolbar"><div className="searchbox"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索报销编号、员工或审核人" aria-label="搜索审核日志"/></div><select value={result} onChange={e=>setResult(e.target.value)} aria-label="结果筛选"><option value="ALL">全部结果</option><option value="自动通过">自动通过</option><option value="驳回">驳回</option><option value="人工复核">人工复核</option><option value="挂起">挂起</option></select><select value={risk} onChange={e=>setRisk(e.target.value)} aria-label="风险筛选"><option value="ALL">全部风险</option><option value="高">高风险</option><option value="中">中风险</option><option value="低">低风险</option></select><span/><button onClick={()=>{setQuery('');setResult('ALL');setRisk('ALL')}}><RefreshCw/>重置</button></div><table><thead><tr><th>报销编号</th><th>员工</th><th>审核时间</th><th>AI 结果</th><th>人工结果</th><th>一致性</th><th>风险</th><th>审核人</th><th></th></tr></thead><tbody>{rows.map(a=>{const e=emp(initialReimbursements.find(r=>r.id===a.reimbursementId)?.employeeId||'E001');const diff=a.manualResult!=='—'&&a.manualResult!==a.aiResult;return <tr className={diff?'diff-row':''} key={a.id} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&openAudit(a.reimbursementId)} onClick={()=>openAudit(a.reimbursementId)}><td><b className="mono">{a.reimbursementId}</b><small>{a.note}</small></td><td>{e.name}</td><td>{a.time}</td><td><Status value={a.aiResult}/></td><td>{a.manualResult==='—'?<span className="muted">—</span>:<Status value={a.manualResult}/>}</td><td>{a.manualResult==='—'?<span className="muted">无需人工</span>:diff?<span className="not-match"><AlertTriangle/>不一致</span>:<span className="match"><Check/>一致</span>}</td><td><Risk value={a.risk}/></td><td>{a.reviewer}</td><td><ChevronRight/></td></tr>})}</tbody></table>{!rows.length&&<Empty text="没有符合筛选条件的审核记录"/>}<div className="pagination"><span>共 {filtered.length} 条记录 · 第 {page}/{pageCount} 页</span><div><button disabled={page===1} onClick={()=>setPage(p=>p-1)}>上一页</button>{Array.from({length:pageCount},(_,i)=><button key={i} className={page===i+1?'active':''} onClick={()=>setPage(i+1)}>{i+1}</button>)}<button disabled={page===pageCount} onClick={()=>setPage(p=>p+1)}>下一页</button></div></div></section><div className="feedback"><div><RefreshCw/></div><p><b>规则反馈闭环正在运行</b><span>AI 判断与人工结果不一致的记录已保存规则版本和输入快照，可用于样本回放。</span></p><button onClick={()=>location.hash='#rules'}>查看规则优化 <ChevronRight/></button></div></>}

function SettingsPage({notify}:{notify:(s:string)=>void}){const [states,setStates]=useState([true,true,true,false]);return <><PageHead eyebrow="企业配置" title="系统设置" desc="管理公司主体、智能服务和消息通知设置。"/><div className="settings-layout"><aside>{['企业信息','智能审核','发票服务','消息通知','权限与安全'].map((x,i)=><button className={i===1?'active':''} key={x}>{x}<ChevronRight/></button>)}</aside><section className="settings-card"><div className="settings-head"><div><h2>智能审核设置</h2><p>配置决策引擎的运行方式和人工兜底策略</p></div></div>{[['启用自动审核','提交报销后自动执行验真、查重、规则和风险评分'],['允许低风险自动通过','全部规则通过且优先级分 ≥ 75 时，自动进入支付队列'],['高风险自动驳回','命中重复发票、购买方错误等底线规则时自动驳回'],['夜间批量审核','每日 02:00 对未处理票据执行批量审核']].map((x,i)=><div className="setting-row" key={x[0]}><div><b>{x[0]}</b><span>{x[1]}</span></div><button className={`switch ${states[i]?'on':''}`} onClick={()=>setStates(states.map((s,n)=>n===i?!s:s))}><i/></button></div>)}<div className="setting-form"><label>自动通过分数阈值<input type="number" defaultValue="75"/><span>分</span></label><label>默认人工审核人<select><option>财务负责人 · 王敏</option><option>财务分析师 · 林琳</option></select></label></div><div className="settings-actions"><button className="primary" onClick={()=>notify('设置已保存')}>保存设置</button></div></section></div></>}
